q(1,"Qualquer pessoa do povo que souber de infração penal em que caiba ação pública poderá",["comunicá-la verbalmente ou por escrito à autoridade policial.","apenas comunicá-la ao Ministério Público.","instaurar o inquérito por conta própria.","exigir a prisão do suspeito.","requisitar diligências à autoridade policial."],"Art. 5º, § 3º.")
