q(1,"Nos crimes de ação privada, a autoridade policial somente poderá proceder a inquérito",["a requerimento de quem tenha qualidade para intentar a ação.","de ofício.","por requisição do Ministério Público.","por determinação do juiz.","por denúncia anônima."],"Art. 5º, § 5º.")
q(1,"Ao tomar conhecimento do crime, a autoridade policial deverá, primeiro, dirigir-se ao local e providenciar para que",["não se alterem o estado e a conservação das coisas até a chegada dos peritos.","as testemunhas sejam ouvidas de imediato.","o suspeito seja interrogado.","as coisas sejam removidas para a delegacia.","o local seja limpo."],"Art. 6º, I.")
q(1,"Entre os deveres da autoridade policial, está",["ouvir o ofendido.","julgar o indiciado.","ouvir somente as testemunhas de defesa.","decretar a prisão preventiva.","arquivar o inquérito."],"Art. 6º, IV.")
q(1,"A autoridade policial deve ordenar a identificação do indiciado pelo processo",["datiloscópico, se possível.","genético, em todos os casos.","fotográfico, apenas.","psicológico.","pericial grafotécnico."],"Art. 6º, VIII.")
q(1,"A reprodução simulada dos fatos pode ser feita pela autoridade policial, desde que",["não contrarie a moralidade ou a ordem pública.","o juiz determine.","o indiciado esteja preso.","haja prévia autorização do Ministério Público.","o ofendido concorde."],"Art. 7º.")
