q(1,"O prazo de término do inquérito, estando o indiciado solto, é de",["30 dias.","10 dias.","45 dias.","15 dias.","90 dias."],"Art. 10, caput.")
q(1,"O inquérito policial acompanhará a denúncia ou a queixa",["sempre que servir de base a uma ou outra.","em qualquer caso.","somente nos crimes de ação pública.","somente se o juiz determinar.","somente se o indiciado estiver preso."],"Art. 12.")
q(1,"Se o indiciado for menor, o curador será nomeado",["pela autoridade policial.","pelo juiz.","pelo Ministério Público.","pelos pais, obrigatoriamente.","pelo advogado."],"Art. 15.")
q(1,"É correto afirmar, nos termos do CPP, que a autoridade policial",["não poderá mandar arquivar autos de inquérito.","pode arquivar o inquérito por falta de provas.","arquiva o inquérito quando a vítima desiste.","arquiva o inquérito após 30 dias.","arquiva o inquérito por conveniência."],"Art. 17.")
q(1,"No inquérito, a autoridade assegurará o sigilo",["necessário à elucidação do fato ou exigido pelo interesse da sociedade.","absoluto, inclusive ao advogado.","apenas durante o interrogatório.","a pedido do indiciado.","por 30 dias, em qualquer caso."],"Art. 20.")
q(1,"A incomunicabilidade do indiciado, quando decretada, não excederá",["três dias.","cinco dias.","dez dias.","24 horas.","trinta dias."],"Art. 21, parágrafo único.")
q(1,"No caso da ocorrência descrita no texto, o inquérito foi instaurado",["de ofício, porque o furto é crime de ação pública incondicionada.","por requisição do juiz.","por representação do dono da subestação.","por requerimento da vítima.","por ordem do Ministério Público."],"O delegado instaurou por conta própria, o que a lei permite nos crimes de ação pública incondicionada (art. 5º, I).","cpp1a")
q(1,"No texto, a primeira providência da autoridade após ciência dos fatos, a determinar, foi",["a ida de peritos ao local.","a soltura dos suspeitos.","o arquivamento do inquérito.","a oitiva das testemunhas.","a decretação de prisão preventiva."],"Art. 6º, I, que prevê a preservação do local até a chegada dos peritos.","cpp1a")
# ---- n=2
q(2,"O requerimento do ofendido para a abertura de inquérito conterá, sempre que possível,",["a narração do fato, a individualização do indiciado e a nomeação das testemunhas.","somente a narração do fato.","a assinatura de duas testemunhas.","a denúncia completa.","o laudo pericial."],"Art. 5º, § 1º.")
q(2,"A autoridade policial deve apreender os objetos relacionados ao fato",["após liberados pelos peritos criminais.","antes da chegada dos peritos.","somente por ordem do juiz.","somente por ordem do Ministério Público.","depois do oferecimento da denúncia."],"Art. 6º, II.")
q(2,"Ao ouvir o indiciado, o termo deverá ser assinado",["por duas testemunhas que lhe tenham ouvido a leitura.","somente pelo escrivão.","por um advogado e um promotor.","pelo juiz.","por três testemunhas."],"Art. 6º, V.")
q(2,"Ao tomar conhecimento do crime, a autoridade deverá colher informações sobre",["a existência de filhos da pessoa presa, suas idades e eventual deficiência.","o patrimônio de todos os parentes do preso.","a religião do indiciado.","a vida sexual do indiciado.","o histórico escolar da vítima."],"Art. 6º, X.")
q(2,"As peças do inquérito serão",["reduzidas a escrito ou datilografadas e, neste caso, rubricadas pela autoridade.","apenas orais.","gravadas em vídeo, obrigatoriamente.","redigidas pelo Ministério Público.","redigidas pelo juiz."],"Art. 9º.")
q(2,"Ao final do inquérito, a autoridade policial fará relatório e enviará os autos",["ao juiz competente.","ao tribunal.","à Defensoria Pública.","ao delegado-geral.","à vítima."],"Art. 10, § 1º.")
q(2,"Quando o fato for de difícil elucidação e o indiciado estiver solto, a autoridade poderá",["requerer ao juiz a devolução dos autos para ulteriores diligências, no prazo que ele marcar.","prorrogar o prazo por conta própria.","arquivar o inquérito.","pedir ao promotor novo prazo.","encerrar o inquérito sem relatório."],"Art. 10, § 3º.")
q(2,"Incumbe ainda à autoridade policial",["representar acerca da prisão preventiva.","decretar a prisão preventiva.","julgar o indiciado.","arquivar os autos.","denunciar o acusado."],"Art. 13, IV.")
q(2,"O requerimento de diligência feito pelo ofendido ou pelo indiciado será",["realizado, ou não, a juízo da autoridade.","sempre realizado.","sempre indeferido.","decidido pelo juiz.","decidido pelo promotor."],"Art. 14.")
q(2,"O Ministério Público poderá requerer a devolução do inquérito à autoridade policial somente",["para novas diligências imprescindíveis ao oferecimento da denúncia.","quando discordar do relatório.","quando houver pedido da vítima.","para exigir prisão preventiva.","por conveniência do promotor."],"Art. 16.")
q(2,"Ordenado o arquivamento do inquérito pelo juiz, por falta de base para a denúncia, a autoridade policial",["poderá proceder a novas pesquisas, se de outras provas tiver notícia.","fica impedida de investigar o fato.","deve reabrir o inquérito de ofício.","deve comunicar a vítima.","deve devolver os documentos ao indiciado."],"Art. 18.")
q(2,"Nos crimes em que não couber ação pública, os autos do inquérito serão remetidos ao juízo competente, onde",["aguardarão a iniciativa do ofendido ou de seu representante legal.","serão arquivados.","serão destruídos.","serão entregues ao Ministério Público.","serão enviados à Defensoria."],"Art. 19.")
q(2,"Nos atestados de antecedentes solicitados, a autoridade policial",["não poderá mencionar anotações sobre instauração de inquérito contra o requerente.","deve listar todos os inquéritos.","deve mencionar apenas os inquéritos arquivados.","deve informar apenas os inquéritos em andamento.","deve indicar o número do inquérito."],"Art. 20, parágrafo único.")
q(2,"A incomunicabilidade do indiciado será decretada",["por despacho fundamentado do juiz, a requerimento da autoridade policial ou do Ministério Público.","por despacho da autoridade policial.","automaticamente, em caso de prisão.","por decisão do promotor.","por ordem do carcereiro."],"Art. 21, parágrafo único.")
q(2,"Quando há mais de uma circunscrição policial na comarca, a autoridade de uma delas poderá",["ordenar diligências em circunscrição de outra, independentemente de precatórias.","atuar apenas dentro da sua circunscrição.","depender sempre de precatória.","pedir ao juiz autorização para cada diligência.","transferir o inquérito ao delegado-geral."],"Art. 22.")
q(2,"Ao remeter o inquérito ao juiz, a autoridade policial oficiará ao Instituto de Identificação e Estatística, informando",["o juízo a que foram distribuídos os autos e os dados da infração e do indiciado.","apenas o nome do indiciado.","somente o número do inquérito.","as testemunhas ouvidas.","o laudo pericial."],"Art. 23.")
q(2,"No texto, o ofendido não quis autorizar a investigação. Em relação ao inquérito, é correto afirmar que",["a autoridade não pode iniciá-lo sem a representação do ofendido, se o crime exigir representação.","a autoridade deve instaurá-lo de ofício, independentemente da vontade da vítima.","o parente do ofendido pode obrigar a polícia a instaurar.","o juiz deve requisitar a instauração.","a representação é desnecessária em qualquer caso."],"Art. 5º, § 4º: em crime que exige representação, sem ela o inquérito não pode ser iniciado.","cpp1b")
q(2,"No texto, o pedido do parente que não é representante legal da vítima",["não tem a qualidade exigida para representar.","obriga a polícia a instaurar o inquérito.","deve ser atendido em 10 dias.","vale como representação em qualquer caso.","dispensa a representação da vítima."],"Quem tem qualidade para representar é a vítima ou seu representante legal (art. 5º, II e § 4º).","cpp1b")
q(2,"Com base no texto da ocorrência dos fios, é correto que a autoridade policial",["instaurou o inquérito de ofício, sem necessidade de representação.","dependeu de requisição do juiz para instaurar.","dependeu da representação do proprietário.","só poderia instaurar a requerimento do dono da subestação.","poderia arquivar o inquérito logo após a instauração."],"Crime de ação pública incondicionada: instauração de ofício (art. 5º, I).","cpp1a")
q(2,"Os instrumentos do crime e os objetos que interessarem à prova",["acompanharão os autos do inquérito.","serão devolvidos ao indiciado.","serão destruídos pela autoridade policial.","ficarão sob guarda da vítima.","serão enviados somente ao Ministério Público."],"Art. 11.")
# ---- n=3
q(3,"Sobre o prazo de dez dias para conclusão do inquérito de indiciado preso preventivamente, é correto afirmar que ele",["conta a partir do dia em que se executar a ordem de prisão.","conta da data do crime.","conta da data da denúncia.","conta da data do decreto da prisão, ainda que não cumprida.","não existe nessa hipótese."],"Art. 10, caput.")
q(3,"Nos crimes de ação privada, a autoridade policial",["somente poderá proceder a inquérito a requerimento de quem tenha qualidade para intentar a ação.","pode instaurar inquérito de ofício, mas não pode concluí-lo.","instaura sempre por requisição do Ministério Público.","pode instaurar mediante qualquer comunicação.","dispensa o requerimento se há flagrante."],"Art. 5º, § 5º.")
q(3,"Nos termos do art. 14-A, o servidor de órgão do art. 144 da Constituição, investigado por fato relacionado ao uso da força letal em serviço, será citado e poderá constituir defensor no prazo de",["até 48 horas, a contar do recebimento da citação.","até 24 horas.","até 5 dias.","até 10 dias.","até 72 horas."],"Art. 14-A, § 1º.")
q(3,"Esgotado o prazo sem que o investigado constitua defensor, a autoridade responsável pela investigação",["intimará a instituição a que ele estava vinculado, que indicará defensor em 48 horas.","nomeará defensor dativo.","dispensará a defesa técnica.","aguardará indefinidamente.","arquivará a investigação."],"Art. 14-A, § 2º.")
q(3,"Havendo necessidade de indicação de defensor nos termos do art. 14-A, a defesa caberá",["preferencialmente à Defensoria Pública.","exclusivamente ao Ministério Público.","aos advogados da instituição, sempre.","a qualquer advogado, por sorteio.","à autoridade policial."],"Art. 14-A, § 3º.")
q(3,"Na hipótese de não atuação da Defensoria Pública, os custos com a defesa do investigado, no caso do art. 14-A, correm por conta",["do orçamento da instituição a que estava vinculado à época dos fatos.","do próprio investigado.","do Poder Judiciário.","do Ministério Público.","da União, em qualquer caso."],"Art. 14-A, § 5º.")
q(3,"Nos crimes de extorsão mediante sequestro, o delegado de polícia poderá requisitar dados cadastrais da vítima ou de suspeitos, e a requisição será atendida no prazo de",["24 horas.","48 horas.","72 horas.","5 dias.","10 dias."],"Art. 13-A, parágrafo único.")
q(3,"No tráfico de pessoas, a requisição às empresas de telecomunicações dos sinais que permitam localizar a vítima, mediante autorização judicial, será fornecida por período não superior a",["30 dias, renovável por uma única vez, por igual período.","10 dias, renovável por tempo indeterminado.","60 dias, sem renovação.","15 dias, renovável duas vezes.","90 dias, sem renovação."],"Art. 13-B, § 2º, II.")
q(3,"Nas hipóteses do art. 13-B, o sinal fornecido pela operadora",["não permite acesso ao conteúdo da comunicação, que depende de autorização judicial.","permite acesso ao conteúdo da comunicação.","dispensa qualquer autorização judicial.","inclui o histórico de chamadas.","é fornecido sem prazo."],"Art. 13-B, § 2º, I.")
q(3,"Nas hipóteses do art. 13-B, o inquérito policial deverá ser instaurado no prazo máximo de",["72 horas, contado do registro da ocorrência.","24 horas.","48 horas.","5 dias.","10 dias."],"Art. 13-B, § 3º.")
q(3,"Assinale a alternativa INCORRETA sobre o inquérito policial.",["A autoridade policial pode mandar arquivar os autos quando não houver indícios.","O inquérito policial deve ser escrito.","Pode ser iniciado por requisição do Ministério Público.","Quando o indiciado está solto, o prazo é de 30 dias.","O indiciado menor terá curador nomeado pela autoridade policial."],"Art. 17: a autoridade policial não pode mandar arquivar.")
q(3,"A incomunicabilidade do indiciado respeitará, em qualquer hipótese,",["o direito do advogado de se comunicar com o cliente.","o direito de visita de familiares.","o direito à comunicação por telefone.","o direito de ser ouvido sem advogado.","o direito de receber correspondência."],"Art. 21, parágrafo único, com remissão ao Estatuto da Advocacia (art. 89, III).")
q(3,"Do despacho que indeferir o requerimento de abertura de inquérito, caberá recurso",["para o chefe de Polícia.","ao juiz.","ao Ministério Público.","ao Tribunal de Justiça.","ao delegado da circunscrição."],"Art. 5º, § 2º.")
q(3,"Sobre a reprodução simulada dos fatos, é correto afirmar que",["não pode contrariar a moralidade ou a ordem pública.","é obrigatória em todo inquérito.","exige a presença do juiz.","só pode ser feita com autorização do Ministério Público.","dispensa a presença do indiciado."],"Art. 7º.")
q(3,"A requisição de diligência feita à autoridade policial pelo juiz ou pelo Ministério Público",["deve ser realizada, nos termos do art. 13, II.","é facultativa, a juízo da autoridade.","só vale se o indiciado concordar.","só vale se o ofendido concordar.","depende de autorização do chefe de Polícia."],"Art. 13, II. Já a diligência pedida pelo ofendido ou indiciado é a juízo da autoridade (art. 14).")
q(3,"Considere as afirmações sobre o art. 6º do CPP: I. A autoridade deve preservar o local até a chegada dos peritos. II. Os objetos apreendidos devem ser liberados antes pelos peritos. III. A autoridade deve ouvir o indiciado sem qualquer formalidade. Está correto o que se afirma em",["I e II, apenas.","I, apenas.","II e III, apenas.","I e III, apenas.","I, II e III."],"A oitiva do indiciado segue formalidades, e o termo é assinado por duas testemunhas (art. 6º, V).")
q(3,"Se o fato for de difícil elucidação, com o indiciado preso, a autoridade",["tem de concluir o inquérito em 10 dias, pois a dilação do art. 10, § 3º, é prevista para o indiciado solto.","pode pedir ao juiz a devolução dos autos para novas diligências.","pode prorrogar o prazo por conta própria.","tem 30 dias.","pode arquivar o inquérito."],"Art. 10, § 3º: a dilação refere-se ao indiciado solto.")
q(3,"Assinale o que NÃO está entre os atos que o art. 6º do CPP atribui à autoridade policial ao tomar conhecimento do crime.",["Decretar a prisão preventiva do indiciado.","Proceder a reconhecimento de pessoas e coisas e a acareações.","Determinar exame de corpo de delito e outras perícias, se for o caso.","Ordenar a identificação do indiciado pelo processo datiloscópico, se possível.","Averiguar a vida pregressa do indiciado."],"A autoridade apenas representa acerca da prisão preventiva (art. 13, IV); quem a decreta é o juiz.")
q(3,"Segundo o texto da ocorrência dos fios, o indiciado preso em flagrante tem o inquérito concluído no prazo de",["10 dias.","30 dias.","15 dias.","60 dias.","5 dias."],"Art. 10: preso em flagrante, 10 dias.","cpp1a")
q(3,"No caso do texto da briga, a autoridade policial",["não pode iniciar o inquérito sem representação, se o crime exigir.","deve iniciar de ofício, em qualquer hipótese.","deve iniciar a pedido do parente, sem outras formalidades.","deve arquivar o procedimento.","deve remeter o caso ao Ministério Público para denúncia imediata."],"Art. 5º, § 4º.","cpp1b")
